/* ===== answer parsing and grading ===== */
function clean(raw){return String(raw).trim().toLowerCase().replace(/[−–—]/g,"-").replace(/[$%,]/g,"").replace(/\s+/g," ").replace(/[a-z°²³.\s]+$/,"").trim();}
function parseNum(raw){
 let s=clean(raw);if(!s)return null;let neg=false;if(s[0]==="-"){neg=true;s=s.slice(1).trim();}
 let m;const sg=n=>neg?-n:n;
 if(m=s.match(/^(\d+)\s+(\d+)\s*\/\s*(\d+)$/)){const w=+m[1],a=+m[2],b=+m[3];if(!b)return null;return{n:sg(w*b+a),d:b,frac:true,mixed:true,reduced:gcd(a,b)===1&&a<b};}
 if(m=s.match(/^(\d+)\s*\/\s*(\d+)$/)){const a=+m[1],b=+m[2];if(!b)return null;return{n:sg(a),d:b,frac:true,mixed:false,reduced:gcd(a,b)===1};}
 if(m=s.match(/^(\d*)\.(\d+)$/)||s.match(/^(\d+)()$/)){const ip=m[1]||"0",dp=m[2]||"";const d=Math.pow(10,dp.length);let n=+(ip+dp);const g=gcd(n,d)||1;return{n:sg(n/g),d:d/g,frac:false,mixed:false,reduced:true};}
 return null;
}
const same=(a,b)=>a.n*b.d===b.n*a.d;
function splitList(v){const s=String(v);return (/[,;]/.test(s)?s.split(/[,;]+/):s.trim().split(/\s+/)).map(x=>x.trim()).filter(Boolean);}
function parseRatio(raw){const s=String(raw).trim().toLowerCase().replace(/\s*to\s*/g,":").replace(/\s+/g,"");const m=s.match(/^(\d+):(\d+)$/);return m?[+m[1],+m[2]]:null;}

function exprNorm(s){return String(s).toLowerCase().replace(/[−–—]/g,"-").replace(/[×·]/g,"*").replace(/÷/g,"/").replace(/\s+/g,"");}
function exprParse(src,vars){
 const s=exprNorm(src);if(!s)return null;const tk=[];let i=0;
 while(i<s.length){const c=s[i];
  if(/[0-9.]/.test(c)){let j=i;while(j<s.length&&/[0-9.]/.test(s[j]))j++;const n=s.slice(i,j);if(!/^(\d+\.?\d*|\.\d+)$/.test(n))return null;tk.push({k:"n",v:+n});i=j;}
  else if(/[a-z]/.test(c)){if(!vars.includes(c))return null;tk.push({k:"v",v:c});i++;}
  else if("+-*/^()".includes(c)){tk.push({k:c});i++;}
  else return null;}
 const t=[];tk.forEach((a,k)=>{if(k>0){const p=tk[k-1];if((p.k==="n"||p.k==="v"||p.k===")")&&(a.k==="n"||a.k==="v"||a.k==="("))t.push({k:"*"});}t.push(a);});
 let p=0;const pk=()=>t[p],eat=k=>{if(t[p]&&t[p].k===k){p++;return true;}return false;};
 function E(){let n=T();if(!n)return null;while(pk()&&(pk().k==="+"||pk().k==="-")){const o=t[p++].k,r=T();if(!r)return null;const l=n;n=o==="+"?e=>l(e)+r(e):e=>l(e)-r(e);}return n;}
 function T(){let n=U();if(!n)return null;while(pk()&&(pk().k==="*"||pk().k==="/")){const o=t[p++].k,r=U();if(!r)return null;const l=n;n=o==="*"?e=>l(e)*r(e):e=>l(e)/r(e);}return n;}
 function U(){if(eat("-")){const n=U();return n?e=>-n(e):null;}if(eat("+"))return U();return W();}
 function W(){const b=A();if(!b)return null;if(eat("^")){const x=U();if(!x)return null;return e=>Math.pow(b(e),x(e));}return b;}
 function A(){const x=pk();if(!x)return null;if(x.k==="n"){p++;return()=>x.v;}if(x.k==="v"){p++;return e=>e[x.v];}if(eat("(")){const n=E();if(!n||!eat(")"))return null;return n;}return null;}
 const f=E();if(!f||p!==t.length)return null;return f;
}
function parsePair(s){const m=String(s).trim().replace(/[−–—]/g,"-").match(/^\(?\s*([^,()]+?)\s*,\s*([^,()]+?)\s*\)?$/);if(!m)return null;const a=parseNum(m[1]),b=parseNum(m[2]);return a&&b?[a,b]:null;}
function gradeQ(q,val){
 if(val==null||String(val).trim()==="")return{ok:false,bad:true,msg:"Type or choose an answer first."};
 const d=dec(q);
 if(q.t==="mc")return{ok:val===d.a};
 if(q.t==="num"){const g=parseNum(val);if(!g)return{ok:false,bad:true,msg:"Type a number, a fraction like 3/4, or a mixed number like 2 1/2."};
  const w=parseNum(d.a);if(!same(g,w))return{ok:false};
  if(d.exact){return(g.frac===w.frac&&g.mixed===w.mixed&&g.n===w.n&&g.d===w.d)?{ok:true}:{ok:false,msg:"That is the right amount, but write it in the form the problem asks for."};}
  if(g.frac&&!g.reduced)return{ok:false,msg:"That is the right amount, but it is not in simplest form. Simplify it and check again."};
  return{ok:true};}
 if(q.t==="list"){const want=d.a.map(parseNum),got=splitList(val).map(parseNum);
  if(got.some(x=>!x))return{ok:false,bad:true,msg:"Type numbers separated by commas."};
  if(got.length!==want.length)return{ok:false};
  return{ok:want.every((w,i)=>same(w,got[i]))};}
 if(q.t==="expr"){const vars=d.vars||["x"];const g=exprParse(val,vars),w=exprParse(d.a,vars);
  if(!g)return{ok:false,bad:true,msg:"Type an expression that uses the letter "+vars.join(" or ")+", like 3"+vars[0]+" + 5."};
  const pts=[2,3.5,-1.5,7,0.25,11];
  const eq=pts.every((v,i)=>{const env={};vars.forEach((x,k)=>env[x]=pts[(i+k)%pts.length]);const a=g(env),b=w(env);return isFinite(a)&&Math.abs(a-b)<1e-6*(1+Math.abs(b));});
  if(!eq)return{ok:false};
  const nv=exprNorm(val).replace(/\*/g,"");
  if(d.form==="expanded"&&nv.includes("("))return{ok:false,msg:"That is equivalent, but the problem asks you to write it without parentheses."};
  if(d.form==="factored"&&!(d.accept||[]).map(x=>exprNorm(x).replace(/\*/g,"")).includes(nv))return{ok:false,msg:"That is equivalent, but write it in factored form using the greatest common factor, like 2(x + 3)."};
  return{ok:true};}
 if(q.t==="pair"){const g=parsePair(val),w=parsePair(d.a);if(!g)return{ok:false,bad:true,msg:"Type an ordered pair like (3, -2)."};
  return{ok:same(g[0],w[0])&&same(g[1],w[1])};}
 if(q.t==="ratio"){const g=parseRatio(val),w=parseRatio(d.a);if(!g)return{ok:false,bad:true,msg:"Write the ratio like 3:5."};
  if(g[0]*w[1]!==g[1]*w[0])return{ok:false};
  if(gcd(g[0],g[1])!==1)return{ok:false,msg:"That is an equivalent ratio, but it is not in simplest form."};
  return{ok:true};}
 return{ok:false};
}
function answerText(q){const d=dec(q);if(q.t==="list")return d.a.join(", ");return d.a;}

/* ===== state and saving ===== */
let S=blankState(),V={view:"home"},TAB="learn",DRAW={},streak=0;
function blankState(){return{v:2,updated:0,a:{},p:{},miles:0,drag:0,term:1};}
const TERM_MODS={1:["m1","m2","m3","m4","m5"],2:["m6","m7","m8","m9","m10"]};
const tOf=it=>it.term||1;
const curT=()=>S.term===2?2:1;
const termItems=t=>ITEMS.filter(it=>tOf(it)===t);
const termLessons=t=>LESSONS.filter(l=>TERM_MODS[t].includes(l.mod));
function A(id){return S.a[id]||(S.a[id]={ans:{},tries:{},first:{},ok:{},flag:{},secs:0,unlocked:false,submitted:false,started:0,idx:0,subAt:0});}
const LS_KEY="m6t1:alex";
function loadLocal(){try{const x=JSON.parse(localStorage.getItem(localKey())||"null");if(x&&x.a){x.p=x.p||{};x.miles=x.miles||0;x.drag=x.drag||0;return x;}}catch(e){}return null;}
let CLOUD=false;
let WHO="",cloudT=null,cloudBusy=false,cloudAgain=false;
const localKey=()=>WHO?LS_KEY+":"+WHO:LS_KEY;
function setStatus(t){const e=$("#savestat");if(e)e.textContent=(WHO?WHO+" | ":"")+t;}
function save(){
 S.updated=Date.now();
 try{localStorage.setItem(localKey(),JSON.stringify(S));}catch(e){}
 if(CLOUD){setStatus("Saving...");clearTimeout(cloudT);cloudT=setTimeout(pushCloud,1500);}
 else setStatus("Saved in this browser");
}
function pushCloud(){
 cloudT=null;
 if(cloudBusy){cloudAgain=true;return;}
 cloudBusy=true;
 google.script.run
  .withSuccessHandler(()=>{cloudBusy=false;setStatus("Saved to your account");if(cloudAgain){cloudAgain=false;pushCloud();}})
  .withFailureHandler(()=>{cloudBusy=false;cloudAgain=false;setStatus("Not saved yet. Check your internet connection.");clearTimeout(cloudT);cloudT=setTimeout(pushCloud,10000);})
  .saveProgress(JSON.stringify(S));
}

/* ===== grades ===== */
function scorable(id){return QS[id].filter(q=>q.t!=="text");}
const PPQ=4;
function qPts(it,q,a){
 if(it.type==="hw"){if(!a.ok[q.id])return 0;const t=a.tries[q.id]||1;return t<=1?4:t===2?3:t===3?2:1;}
 if(a.ok[q.id])return 4;const v=a.ans[q.id];if(v===undefined||String(v).trim()==="")return 0;return a.work&&a.work[q.id]?2:1;
}
function bandOf(r){return Math.floor((40*r.earned+r.total)/(2*r.total))*5;}
function keywordFor(it){const r=result(it);if(!r||!r.done||!KW[it.id])return null;return KW[it.id][bandOf(r)/5];}
function result(it){
 const a=S.a[it.id];if(!a)return null;const qs=scorable(it.id);
 const total=qs.length*PPQ;
 const earned=qs.reduce((s,q)=>s+qPts(it,q,a),0);
 const first=qs.reduce((s,q)=>s+(a.first[q.id]===true?q.pts:0),0);
 let done,started=Object.keys(a.ans).length>0||Object.keys(a.tries).length>0||a.started;
 if(it.type==="hw")done=qs.every(q=>a.ok[q.id]);else done=!!a.submitted;
 return{earned,total,pct:total?earned/total*100:0,firstPct:total?first/total*100:0,done,started:!!started};
}
function itemWeight(it){const n=ITEMS.filter(x=>x.cat===it.cat&&tOf(x)===tOf(it)).length;return CFG.weights[it.cat]/n;}
function termGrade(t){
 t=t||curT();let num=0,den=0;termItems(t).forEach(it=>{const r=result(it);if(r&&r.done){const w=itemWeight(it);num+=w*r.pct;den+=w;}});
 return den?num/den:null;
}
function rankFor(g){if(g===null)return"Cadet";if(g>=90)return"Captain";if(g>=80)return"First Officer";if(g>=70)return"Pilot";return"Student Pilot";}

/* ===== work area ===== */
function niceStep(r){const c=[1,2,5,10,20,25,50,100,200];const t=r/10;return c.find(x=>x>=t)||250;}
function nlBg(lo,hi){
 const x0=50,x1=650,y=200,step=niceStep(hi-lo),sx=v=>x0+(v-lo)*(x1-x0)/(hi-lo);
 let s=`<svg viewBox="0 0 700 400" preserveAspectRatio="xMidYMid meet"><line x1="${x0-24}" y1="${y}" x2="${x1+24}" y2="${y}" stroke="#14213d" stroke-width="4"/><path d="M${x0-24} ${y} l14 -9 v18z M${x1+24} ${y} l-14 -9 v18z" fill="#14213d"/>`;
 for(let v=Math.ceil(lo/step)*step;v<=hi+1e-9;v+=step){const c=v===0;s+=`<line x1="${sx(v)}" y1="${y-(c?20:14)}" x2="${sx(v)}" y2="${y+(c?20:14)}" stroke="${c?"#DD0426":"#14213d"}" stroke-width="${c?4:3}"/><text x="${sx(v)}" y="${y+46}" text-anchor="middle" font-size="24" font-weight="800" fill="${c?"#DD0426":"#14213d"}">${v}</text>`;}
 return s+"</svg>";
}
function planeBg(x0,x1,y0,y1){
 const W=700,H=Math.round(W*(y1-y0)/(x1-x0)),pad=34,sx=v=>pad+(v-x0)*(W-2*pad)/(x1-x0),sy=v=>pad+(y1-v)*(H-2*pad)/(y1-y0);
 let s=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet">`;
 for(let v=x0;v<=x1;v++){s+=`<line x1="${sx(v)}" y1="${pad}" x2="${sx(v)}" y2="${H-pad}" stroke="${v===0?"#14213d":"#b8c7da"}" stroke-width="${v===0?3.5:1.3}"/>`;if(v!==0)s+=`<text x="${sx(v)}" y="${sy(0)+20}" text-anchor="middle" font-size="16" font-weight="700" fill="#14213d">${v}</text>`;}
 for(let v=y0;v<=y1;v++){s+=`<line x1="${pad}" y1="${sy(v)}" x2="${W-pad}" y2="${sy(v)}" stroke="${v===0?"#14213d":"#b8c7da"}" stroke-width="${v===0?3.5:1.3}"/>`;if(v!==0)s+=`<text x="${sx(0)-8}" y="${sy(v)+5}" text-anchor="end" font-size="16" font-weight="700" fill="#14213d">${v}</text>`;}
 return s+"</svg>";
}
function workHTML(q){
 let bg="",cls="blank",ar="";
 if(q.work&&q.work.startsWith("nl:")){const[,a,b]=q.work.split(":");bg=nlBg(+a,+b);cls="";}
 else if(q.work&&q.work.startsWith("plane:")){const[,a,b,c,d]=q.work.split(":").map((x,i)=>i?+x:x);bg=planeBg(a,b,c,d);cls="";ar=(b-a)+"/"+(d-c);}
 const colors=["#14213d","#DD0426","#1f6fd1","#0a8a37"];
 return `<div class="card work"><div class="wtools"><b>Work area</b>${colors.map((c,i)=>`<button class="dot${i===0?" sel":""}" data-c="${c}" style="background:${c}" aria-label="Pen color ${i+1}"></button>`).join("")}<button class="ghost" id="weras">Eraser</button><button class="ghost" id="wclr">Clear</button></div><div class="wbox ${cls}" id="wbox" style="${ar?`aspect-ratio:${ar};min-height:420px`:"height:max(560px,calc(100vh - 170px))"}">${bg}<canvas id="wcv"></canvas></div><p class="tip">Draw, graph, or show your work here. Your drawing is not graded.</p></div>`;
}
function mountWork(q){
 const cv=$("#wcv"),box=$("#wbox");if(!cv)return;
 const r=box.getBoundingClientRect(),dpr=window.devicePixelRatio||1;
 cv.width=Math.max(1,r.width*dpr);cv.height=Math.max(1,r.height*dpr);
 const ctx=cv.getContext("2d");ctx.scale(dpr,dpr);ctx.lineCap="round";ctx.lineJoin="round";
 if(DRAW[q.id]){const img=new Image();img.onload=()=>{ctx.drawImage(img,0,0,r.width,r.height);};img.src=DRAW[q.id];}
 let color="#14213d",erase=false,down=false,lx=0,ly=0;
 const setCur=()=>{let svg,h;if(erase){svg=`<svg xmlns="http://www.w3.org/2000/svg" width="28" height="28"><circle cx="14" cy="14" r="12.5" fill="rgba(255,255,255,.6)" stroke="#14213d" stroke-width="1.5" stroke-dasharray="3 2"/></svg>`;h=14;}else{svg=`<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16"><circle cx="8" cy="8" r="5" fill="${color}" stroke="#fff" stroke-width="2"/><circle cx="8" cy="8" r="6.5" fill="none" stroke="#14213d" stroke-width="1"/></svg>`;h=8;}cv.style.cursor=`url("data:image/svg+xml,${encodeURIComponent(svg)}") ${h} ${h}, crosshair`;$("#weras").classList.toggle("on",erase);};
 setCur();
 const pos=e=>{const b=cv.getBoundingClientRect();return[e.clientX-b.left,e.clientY-b.top];};
 cv.addEventListener("pointerdown",e=>{down=true;[lx,ly]=pos(e);cv.setPointerCapture(e.pointerId);e.preventDefault();});
 cv.addEventListener("pointermove",e=>{if(!down)return;const[x,y]=pos(e);ctx.globalCompositeOperation=erase?"destination-out":"source-over";ctx.strokeStyle=color;ctx.lineWidth=erase?26:3.5;ctx.beginPath();ctx.moveTo(lx,ly);ctx.lineTo(x,y);ctx.stroke();lx=x;ly=y;});
 const up=()=>{if(down){down=false;DRAW[q.id]=cv.toDataURL();if(V.view==="run"&&S.a[V.id]){const a=S.a[V.id];a.work=a.work||{};if(!a.submitted){a.work[q.id]=true;saveSoft();}}}};
 cv.addEventListener("pointerup",up);cv.addEventListener("pointercancel",up);
 document.querySelectorAll(".wtools .dot").forEach(b=>b.onclick=()=>{color=b.dataset.c;erase=false;document.querySelectorAll(".wtools .dot").forEach(x=>x.classList.remove("sel"));b.classList.add("sel");setCur();});
 $("#weras").onclick=()=>{erase=true;document.querySelectorAll(".wtools .dot").forEach(x=>x.classList.remove("sel"));setCur();};
 $("#wclr").onclick=()=>{ctx.globalCompositeOperation="source-over";ctx.clearRect(0,0,r.width,r.height);delete DRAW[q.id];};
}

/* ===== modal ===== */
function modal(html){const m=$("#modal");m.innerHTML=`<div class="dlg" role="dialog" aria-modal="true">${html}</div>`;m.hidden=false;return m;}
function closeModal(){const m=$("#modal");m.hidden=true;m.innerHTML="";}
function askCode(title,msg){
 return new Promise(res=>{
  modal(`<h2>${esc(title)}</h2><p>${esc(msg)}</p><input type="text" id="codein" autocomplete="off" autocapitalize="characters" aria-label="Code"><div class="msg bad" id="codemsg"></div><div class="row"><button id="codeok">Continue</button><button class="ghost" id="codeno">Cancel</button></div>`);
  const inp=$("#codein");inp.focus();
  const go=()=>{res(inp.value.trim());closeModal();};
  $("#codeok").onclick=go;$("#codeno").onclick=()=>{res(null);closeModal();};
  inp.addEventListener("keydown",e=>{if(e.key==="Enter")go();});
 });
}
function manualHTML(mod){const m=MANUAL[mod];return `<h4>Formulas and key facts</h4><ul>${m.f.map(x=>`<li>${esc(x)}</li>`).join("")}</ul><h4>How to solve it</h4><ol>${m.s.map(x=>`<li>${esc(x)}</li>`).join("")}</ol>`;}
function openManual(mods){
 modal(`<h2>Flight manual</h2>${mods.map(m=>`<div class="manual"><h3 style="font-size:23px;margin-top:10px">${esc(MANUAL[m].title)}</h3>${manualHTML(m)}</div>`).join("")}<div class="row"><button id="mclose">Close</button></div>`);
 $("#mclose").onclick=closeModal;
}


function fleetOf(id){const k=SLOT[id];return k?FLEET[k]:null;}
function picHTML(id){const p=fleetOf(id);if(!p)return "";if(!unlockedVia(id)){const l=LESSONS.find(x=>x.id===id);return `<div class="picph mystery" aria-label="Mystery plane or ship"><span class="qmark">?</span><span>Mystery plane or ship</span><span style="font-weight:700;font-size:14px">${l?"Open the lesson to reveal it":"Finish this to reveal it"}</span></div>`;}if(!p.img)return `<div class="picph" aria-hidden="true">${JET.replace('class="jet"','')}<span>Picture coming soon</span></div>`;return `<button class="pic" data-fact="${id}" aria-label="${esc(p.n)} fact card" style="background:url(${p.img}) center/cover"></button>`;}
function factHTML(id){const p=fleetOf(id);if(!p)return "";return `<div class="factcard">${p.img?`<img src="${p.img}" alt="${esc(p.n)}">`:`<div class="picph">${JET.replace('class="jet"','')}<span>Picture coming soon</span></div>`}<div><span class="kchip ${p.k!=="Plane"?"ship":""}">${p.k}</span><h4>${esc(p.n)}</h4><p style="margin:0">${esc(p.f)}</p></div></div>`;}
function openFact(id){modal(`<h2>Fact card</h2>${factHTML(id)}<div class="row"><button id="mclose">Close</button></div>`);$("#mclose").onclick=closeModal;}
function bindFacts(){document.querySelectorAll("[data-fact]").forEach(b=>b.onclick=()=>openFact(b.dataset.fact));}
function unlockedVia(id){const l=LESSONS.find(x=>x.id===id);if(l)return !!((S.seen&&S.seen[id])||(S.p[id]&&S.p[id].done));const it=itemById(id);if(it){const r=result(it);return !!(r&&r.done);}return false;}
function museumTab(){
 const T=curT();const ids=[...termLessons(T).map(l=>l.id),...termItems(T).map(i=>i.id)].filter(id=>SLOT[id]);
 const got=ids.filter(unlockedVia).length;
 if(!ids.length)return `<p class="tip" style="margin:14px 2px">Term ${T} planes and ships are on their way.</p>`;
 return `<p class="tip" style="margin:14px 2px 0">Open a lesson or finish an assignment to reveal its plane or ship. Tap a picture for its fact card.</p><h2 class="modh">Term ${T} museum: ${got} of ${ids.length} collected</h2><div class="grid mus">${ids.map(id=>{const p=fleetOf(id),u=unlockedVia(id);const l=LESSONS.find(x=>x.id===id),it=itemById(id);const src=l?`Lesson: ${l.title}`:`${it.title}`;
  return `<div class="card item ${u?"":"locked"}">${picHTML(id)}${u?`<span class="kchip ${p.k!=="Plane"?"ship":""}">${p.k}</span>`:""}<h3>${u?esc(p.n):"Locked"}</h3><p class="sub">${u?esc(p.f):`Unlock it: ${esc(src)}`}</p></div>`;}).join("")}</div>`;
}
/* ===== views ===== */
const JET=`<svg class="jet" viewBox="0 0 420 130" aria-hidden="true"><defs><linearGradient id="jb" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ffffff"/><stop offset="1" stop-color="#c9d4e2"/></linearGradient></defs><path d="M20 70 Q30 44 70 42 L330 42 Q392 46 408 66 Q392 84 330 88 L70 90 Q30 90 20 70z" fill="url(#jb)" stroke="#6b7a90" stroke-width="2"/><path d="M60 44 L30 6 L70 6 L112 44z" fill="#DD0426" stroke="#8d0319" stroke-width="2"/><path d="M168 66 L112 118 L168 118 L252 76z" fill="#dfe6ef" stroke="#6b7a90" stroke-width="2"/><rect x="250" y="88" width="46" height="16" rx="8" fill="#b9c4d3" stroke="#6b7a90" stroke-width="2"/><path d="M356 50 L384 52 Q396 58 398 64 L360 62z" fill="#1d3557"/><g fill="#5b7aa3">${Array.from({length:14},(_,i)=>`<rect x="${112+i*15}" y="58" width="7" height="9" rx="3"/>`).join("")}</g><path d="M20 70 L408 66" stroke="#DD0426" stroke-width="4" fill="none" opacity=".0"/></svg>`;
function topbar(){
 return `<div class="topbar"><div class="brand">${LOGO_DATA?`<img src="${LOGO_DATA}" alt="CGA logo">`:""}<span>Pilot Academy</span></div><div class="userchip"><span id="savestat"></span></div></div>`;
}
function bindTop(){}
function statusOf(it){
 const r=result(it);if(!r||!r.started)return{t:"Not started",c:""};
 if(it.type==="hw"){const n=scorable(it.id).filter(q=>A(it.id).ok[q.id]).length;return r.done?{t:`Complete: ${r.pct.toFixed(0)}%`,c:"done"}:{t:`In progress: ${n} of ${scorable(it.id).length} correct`,c:"prog"};}
 return r.done?{t:`Submitted: ${r.pct.toFixed(0)}%`,c:"done"}:{t:"In progress",c:"prog"};
}
const TYPE_LABEL={hw:"Homework",exam:"Exam",term:"Term exam",project:"Project"};
const TABS=[{id:"learn",label:"Learning and Guided Practice"},{id:"hw",label:"Homework"},{id:"exams",label:"Exams"},{id:"end",label:"End of Term: Exam and Project"},{id:"museum",label:"Museum"}];
function starSVG(on){return `<svg viewBox="0 0 24 24" width="30" height="30" aria-hidden="true"><path d="M12 2l3 6.6 7.2.8-5.4 4.9 1.6 7.1L12 17.6 5.6 21.4l1.6-7.1L1.8 9.4 9 8.6z" fill="${on?"#f2b705":"none"}" stroke="${on?"#b98700":"#9aa8bd"}" stroke-width="1.6"/></svg>`;}
function itemCard(it){
 const st=statusOf(it),r=result(it);
 const label=!r||!r.started?"Start":(r.done?(it.type==="hw"?"Review":"Review results"):"Continue");
 const hasMan=it.type==="hw"||it.type==="project";const kw=keywordFor(it);
 return `<div class="card item">${picHTML(it.id)}<span class="chip ${it.type}">${TYPE_LABEL[it.type]}</span><h3>${esc(it.title)}</h3><p class="sub">${esc(it.sub)}</p><div class="meta">About ${it.min} minutes | ${esc(it.when)}</div><div class="status ${st.c}">${esc(st.t)}</div>${r&&r.done&&it.type==="hw"?`<div class="meta">First try score: ${r.firstPct.toFixed(0)}%</div>`:""}${r&&r.done&&it.type==="project"?`<div class="meta">Auto-scored parts only. Your teacher scores the writing.</div>`:""}${kw?`<div class="meta">Mission keyword: <b>${esc(kw)}</b></div>`:""}<div class="row"><button data-open="${it.id}">${label}</button>${r&&r.done&&it.type==="hw"?`<button class="ghost" data-rev="${it.id}">Results</button>`:""}${hasMan?`<button class="ghost" data-man="${it.id}">Flight manual</button>`:""}</div></div>`;
}
function learnTab(){
 const mods=TERM_MODS[curT()];
 return `<p class="tip" style="margin:14px 2px 0">Work through these lessons together. Each lesson has a short mini-lesson, then guided practice. Earn flight miles for correct answers.</p>`+mods.map(m=>`<h2 class="modh">${esc(MANUAL[m].title)}</h2><div class="grid">${LESSONS.filter(l=>l.mod===m).map(l=>{const p=S.p[l.id];const dn=p&&p.done;return `<div class="card item">${picHTML(l.id)}<span class="chip">Lesson</span><h3>${esc(l.title)}</h3><div class="status ${dn?"done":""}">${dn?"Complete":"Not started"}</div>${dn?`<div class="stars" aria-label="${p.stars} of 3 stars">${[1,2,3].map(n=>starSVG(n<=p.stars)).join("")}</div>`:""}<div class="row"><button data-learn="${l.id}">${dn?"Review lesson":"Open lesson"}</button><button class="ghost" data-prac="${l.id}">Guided practice</button></div></div>`;}).join("")}</div>`).join("");
}
function home(){
 V={view:"home"};
 const T=curT(),TI=termItems(T),TL=termLessons(T);
 const g=termGrade(T),done=TI.filter(it=>{const r=result(it);return r&&r.done;}).length;
 const lessonsDone=TL.filter(l=>S.p[l.id]&&S.p[l.id].done).length;
 const tabs=`<div class="tabs" role="tablist">${TABS.map(t=>`<button class="tab${TAB===t.id?" on":""}" role="tab" aria-selected="${TAB===t.id}" data-tab="${t.id}">${t.label}</button>`).join("")}</div>`;
 let body;
 if(TAB==="learn")body=learnTab();
 else if(TAB==="museum")body=museumTab();
 else{const types=TAB==="hw"?["hw"]:TAB==="exams"?["exam"]:["term","project"];body=`<div class="grid">${TI.filter(it=>types.includes(it.type)).map(itemCard).join("")}</div>`;}
 const names={hw:"Homework",exam:"Exams (summative)",end:`Term ${T} exam and project`};
 const rows=Object.keys(CFG.weights).map(cat=>{const its=TI.filter(x=>x.cat===cat);const dn=its.filter(x=>{const r=result(x);return r&&r.done;});const avg=dn.length?dn.reduce((s,x)=>s+result(x).pct,0)/dn.length:null;return `<tr><td>${names[cat]}</td><td>${CFG.weights[cat]}%</td><td>${dn.length} of ${its.length}</td><td>${avg===null?"-":avg.toFixed(1)+"%"}</td></tr>`;}).join("");
 const other=T===1?2:1,og=termGrade(other);
 const sw=`<div class="termsw" role="group" aria-label="Choose a term">${[1,2].map(n=>`<button class="tsw${n===T?" on":""}" data-term="${n}" aria-pressed="${n===T}">Term ${n}</button>`).join("")}</div>`;
 app.innerHTML=topbar()+`<div class="hero">${sw}<h1>Alex’s Pilot Academy</h1><p>Math 6 | Term ${T} | Modules ${T===1?"1 to 5":"6 to 10"}</p><div class="stats"><div class="stat"><b>${rankFor(g)}</b>Rank</div><div class="stat"><b>${g===null?"-":g.toFixed(1)+"%"}</b>Term ${T} grade so far</div><div class="stat"><b>${S.miles}</b>Flight miles</div><div class="stat"><b>${S.drag}</b>Drag</div><div class="stat"><b>${lessonsDone} of ${TL.length}</b>Lessons done</div><div class="stat"><b>${done} of ${TI.length}</b>Graded missions</div></div>${JET}</div>${tabs}${body}
 <div class="card" style="margin-top:18px"><h2 style="font-size:26px">Term ${T} grade book</h2><table class="gb"><tr><th>Category</th><th>Weight</th><th>Finished</th><th>Average</th></tr>${rows}</table>${og!==null?`<p class="meta">Term ${other} grade: ${og.toFixed(1)}%</p>`:""}<p class="tip">Weights follow the CGA grading categories for math courses: classwork and homework 40%, summative assessments 40%, term exam and project 20%. Each term is graded on its own. Your teacher posts the official grades in Learning Lab.</p><div class="row"><button class="ghost" id="treset" style="font-size:16px;padding:6px 12px">Teacher tools</button></div></div>`;
 document.querySelectorAll("[data-tab]").forEach(b=>b.onclick=()=>{TAB=b.dataset.tab;home();});
 document.querySelectorAll("[data-term]").forEach(b=>b.onclick=()=>{S.term=+b.dataset.term;home();window.scrollTo(0,0);});
 document.querySelectorAll("[data-open]").forEach(b=>b.onclick=()=>openItem(b.dataset.open));
 document.querySelectorAll("[data-rev]").forEach(b=>b.onclick=()=>review(b.dataset.rev));
 document.querySelectorAll("[data-man]").forEach(b=>b.onclick=()=>openManual(itemById(b.dataset.man).mods));
 document.querySelectorAll("[data-learn]").forEach(b=>b.onclick=()=>learn(b.dataset.learn));
 document.querySelectorAll("[data-prac]").forEach(b=>b.onclick=()=>startPractice(b.dataset.prac));
 $("#treset").onclick=teacherTools;
 bindFacts();
 save();
}
async function teacherTools(){
 const code=await askCode("Teacher tools","Enter the teacher code.");if(code===null)return;
 if(btoa(code)!==CFG.teacherCode){alert("That code is not correct.");return;}
 modal(`<h2>Teacher tools</h2><p>Choose an item to reset. This clears answers, tries, and time for that item.</p><div class="row">${termItems(curT()).map(it=>`<button class="ghost" data-r="${it.id}" style="font-size:16px;padding:6px 12px">${esc(it.title.split(":")[0])}</button>`).join("")}</div><p style="margin-top:14px">Or clear all guided practice progress, flight miles, and drag.</p><div class="row"><button class="ghost" id="rprac" style="font-size:16px;padding:6px 12px">Reset guided practice</button><button id="mclose">Close</button></div>`);
 $("#mclose").onclick=closeModal;
 document.querySelectorAll("[data-r]").forEach(b=>b.onclick=()=>{if(confirm("Reset "+b.dataset.r+"? This cannot be undone.")){delete S.a[b.dataset.r];save();closeModal();home();}});
 $("#rprac").onclick=()=>{if(confirm("Reset all guided practice, flight miles, and drag? This cannot be undone.")){S.p={};S.miles=0;S.drag=0;streak=0;save();closeModal();home();}};
}
async function openItem(id){
 const it=itemById(id),a=A(id),r=result(it);
 if(a.submitted){return review(id);}
 if(it.code&&!a.unlocked){
  const code=await askCode(it.title,"Your teacher will give you the start code for this exam.");if(code===null)return;
  if(btoa(code.toUpperCase())!==it.code){alert("That code is not correct. Ask your teacher.");return;}
  a.unlocked=true;save();
 }
 if(!a.started&&it.type!=="hw"){
  const rules=it.type==="project"?"This project has number parts that are scored by the computer and writing parts that your teacher scores. You can use the flight manual. Each number part is worth 4 points, and showing your work in the work area earns partial credit. Submit when you are finished to get your mission keyword.":"This is a one-attempt assessment. You can move between questions and flag ones to check later. There are no hints and no flight manual. Each question is worth 4 points. A wrong answer still earns 2 points if you show your work in the work area, or 1 point if you tried. Blank answers earn 0. When you submit, your answers are locked and you get a mission keyword.";
  const go=await new Promise(res=>{modal(`<h2>${esc(it.title)}</h2><p>${esc(it.sub)}</p><div style="max-width:320px">${picHTML(it.id)}</div><div class="warn">About ${it.min} minutes. ${esc(rules)} Use paper and a pencil for your work.</div><div class="row"><button id="beg">Begin</button><button class="ghost" id="nob">Not yet</button></div>`);$("#beg").onclick=()=>{closeModal();res(true);};$("#nob").onclick=()=>{closeModal();res(false);};});
  if(!go)return;
 }
 a.started=a.started||Date.now();save();run(id);
}
function qOrder(id){return QS[id];}
function run(id,idx){
 const it=itemById(id),a=A(id),qs=qOrder(id);
 if(idx!==undefined)a.idx=idx;
 a.idx=Math.min(Math.max(a.idx||0,0),qs.length-1);
 V={view:"run",id};
 const q=qs[a.idx],isHW=it.type==="hw";
 const val=a.ans[q.id]??"";
 const ok=!!a.ok[q.id];
 const pills=qs.map((x,i)=>{let c="pill";if(isHW){if(a.ok[x.id])c+=" ok";else if((a.tries[x.id]||0)>0)c+=" bad";}else{if(a.ans[x.id]!==undefined&&String(a.ans[x.id]).trim()!=="")c+=" ans";if(a.flag[x.id])c+=" flag";}if(i===a.idx)c+=" cur";return `<button class="${c}" data-go="${i}" aria-label="Question ${i+1}">${i+1}</button>`;}).join("");
 let inputHTML="";
 if(q.t==="mc"){
  const order=shuffled(q.choices,hashStr(q.id));
  inputHTML=`<div class="choices" role="radiogroup">${order.map((c,i)=>{let cls="choice";if(val===c)cls+=ok&&isHW?" good":" sel";return `<button class="${cls}" data-ch="${i}" ${ok&&isHW?"disabled":""}><span class="k">${"ABCD"[i]}</span><span>${esc(c)}</span></button>`;}).join("")}</div>`;
  a._order=order;
 }else if(q.t==="text"){
  inputHTML=`<textarea id="ans" ${a.submitted?"disabled":""} aria-label="Your written answer" placeholder="Write your answer here.">${esc(val)}</textarea>`;
 }else{
  const ph=q.t==="list"?"Separate with commas":q.t==="ratio"?"Like 3:5":q.t==="expr"?"Like 3x + 5":q.t==="pair"?"Like (3, -2)":"Type your answer";
  inputHTML=`<input type="text" id="ans" autocomplete="off" autocapitalize="off" spellcheck="false" value="${esc(val)}" placeholder="${ph}" aria-label="Your answer" ${ok&&isHW?"disabled class=\"good\"":""}>${q.t==="num"?`<p class="tip">Fractions look like 3/4. Mixed numbers look like 2 1/2. Negative numbers look like -5.</p>`:q.t==="expr"?`<p class="tip">Use the letter from the question. Write 3x for 3 times x, x^2 for x squared, and n/4 for n divided by 4.</p>`:q.t==="pair"?`<p class="tip">Write the x-coordinate first, then the y-coordinate, like (3, -2).</p>`:""}`;
 }
 const last=a.idx===qs.length-1;
 const modsForQ=[q.mod];
 const canMan=isHW||it.type==="project";
 app.innerHTML=topbar()+`<div class="rtop"><div><button class="ghost" id="hang">Back to hangar</button></div><div><b>${esc(it.title)}</b></div><div class="timer" id="timer">${fmtTime(a.secs)}</div></div><p class="tip" style="margin:4px 0">Suggested time: ${it.min} minutes${isHW?" | Points: 4 if right on the first try, 3 on the second try, 2 after the hint, 1 after that":" | Each question is worth 4 points. Show your work for partial credit."}</p><div class="pills" aria-label="Question navigator">${pills}</div>
 <div class="runner"><div class="card"><div class="qnum">Question ${a.idx+1} of ${qs.length}${a.flag[q.id]?" | Flagged":""}</div>${it.intro&&a.idx===0?`<div class="scenario">${esc(it.intro)}</div>`:""}<div class="qtext">${esc(q.q)}</div>${q.fig?`<div class="fig">${q.fig}</div>`:""}${inputHTML}
 <div class="msg" id="fb" role="status" aria-live="polite"></div>
 ${canMan?`<details class="ref"><summary>Need a reminder? Formulas and how-to</summary>${manualHTML(q.mod)}</details>`:""}
 <div class="foot"><div class="row" style="margin:0"><button class="ghost" id="prev" ${a.idx===0?"disabled":""}>Back</button>${isHW?`<button id="check" ${ok?"disabled":""}>Check answer</button>`:(q.t==="text"?"":`<button class="ghost" id="flag">${a.flag[q.id]?"Remove flag":"Flag for review"}</button>`)}<button class="${isHW?"ghost":""}" id="next" ${last?"disabled":""}>Next</button></div>${isHW?"":`<button class="navy" id="submit">Submit ${it.type==="project"?"project":"exam"}</button>`}</div></div>
 ${workHTML(q)}</div>`;
 bindTop();
 $("#hang").onclick=()=>{home();};
 document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>{persistInput(id,q);run(id,+b.dataset.go);});
 $("#prev").onclick=()=>{persistInput(id,q);run(id,a.idx-1);};
 $("#next").onclick=()=>{persistInput(id,q);run(id,a.idx+1);};
 const ans=$("#ans");
 if(ans){ans.addEventListener("input",()=>{a.ans[q.id]=ans.value;saveSoft();});if(!ok||!isHW)ans.focus();
  ans.addEventListener("keydown",e=>{if(e.key==="Enter"&&q.t!=="text"){if(isHW)hwCheck(id,q);else if(!last){persistInput(id,q);run(id,a.idx+1);}}});}
 document.querySelectorAll("[data-ch]").forEach(b=>b.onclick=()=>{a.ans[q.id]=a._order[+b.dataset.ch];save();document.querySelectorAll("[data-ch]").forEach(x=>x.classList.remove("sel"));b.classList.add("sel");const p=document.querySelector(`[data-go="${a.idx}"]`);if(p&&!isHW)p.classList.add("ans");});
 if(isHW){$("#check").onclick=()=>hwCheck(id,q);}
 else{const f=$("#flag");if(f)f.onclick=()=>{a.flag[q.id]=!a.flag[q.id];save();run(id);};$("#submit").onclick=()=>submitItem(id);}
 mountWork(q);
 save();
}
let softT=null;function saveSoft(){clearTimeout(softT);softT=setTimeout(()=>save(),600);}
function persistInput(id,q){const a=A(id),el=$("#ans");if(el&&!el.disabled)a.ans[q.id]=el.value;}
function hwCheck(id,q){
 const a=A(id),fbx=$("#fb"),ans=$("#ans");
 persistInput(id,q);
 const val=a.ans[q.id];const r=gradeQ(q,val);
 if(r.bad){fbx.className="msg show bad";fbx.innerHTML=esc(r.msg);return;}
 a.tries[q.id]=(a.tries[q.id]||0)+1;
 if(a.first[q.id]===undefined)a.first[q.id]=r.ok;
 if(r.ok){
  a.ok[q.id]=true;save();
  const qs=qOrder(id),allDone=scorable(id).every(x=>a.ok[x.id]);
  fbx.className="msg show good";fbx.innerHTML=`Correct!${allDone?`<small>You finished every problem. Mission complete! Your mission keyword is <b>${esc(keywordFor(itemById(id)))}</b>. Type it into the Learning Lab assignment.</small>`:""}`;
  if(ans){ans.disabled=true;ans.classList.add("good");}
  document.querySelectorAll("[data-ch]").forEach(b=>{b.disabled=true;if(b.classList.contains("sel")){b.classList.remove("sel");b.classList.add("good");}});
  const c=$("#check");if(c)c.disabled=true;
  const pill=document.querySelector(`[data-go="${a.idx}"]`);if(pill){pill.classList.remove("bad");pill.classList.add("ok");}
 }else{
  save();
  const tries=a.tries[q.id];
  fbx.className="msg show bad";
  fbx.innerHTML=`Not yet. Try again!${r.msg?`<small>${esc(r.msg)}</small>`:(tries>=2&&q.hint?`<small>Hint: ${esc(q.hint)}</small>`:`<small>Check your work on paper and try once more.</small>`)}`;
  if(ans){ans.classList.add("bad");setTimeout(()=>ans.classList.remove("bad"),900);ans.select();}
  document.querySelectorAll("[data-ch]").forEach(b=>{if(b.classList.contains("sel")){b.classList.remove("sel");b.classList.add("bad");setTimeout(()=>b.classList.remove("bad"),900);}});
  const pill=document.querySelector(`[data-go="${a.idx}"]`);if(pill)pill.classList.add("bad");
 }
}
function submitItem(id){
 const it=itemById(id),a=A(id),qs=qOrder(id);
 const cur=qs[a.idx];persistInput(id,cur);
 const un=qs.filter(q=>q.t!=="text"?(a.ans[q.id]===undefined||String(a.ans[q.id]).trim()===""):false).length;
 const unT=qs.filter(q=>q.t==="text"&&!String(a.ans[q.id]||"").trim()).length;
 const msg=(un||unT)?`You have ${un+unT} unanswered question${un+unT===1?"":"s"}. `:"";
 modal(`<h2>Submit ${esc(it.title)}?</h2><div class="warn">${msg}After you submit, your answers are locked.</div><div class="row"><button id="yes">Yes, submit</button><button class="ghost" id="no">Keep working</button></div>`);
 $("#no").onclick=closeModal;
 $("#yes").onclick=()=>{
  closeModal();
  qs.forEach(q=>{if(q.t==="text")return;const r=gradeQ(q,a.ans[q.id]);a.ok[q.id]=!!r.ok;if(a.first[q.id]===undefined)a.first[q.id]=!!r.ok;});
  a.submitted=true;a.subAt=Date.now();save(true);review(id);
 };
}
function review(id){
 const it=itemById(id),a=A(id),qs=qOrder(id),r=result(it);
 V={view:"review",id};
 const items=qs.map((q,i)=>{
  if(q.t==="text")return `<div class="rq"><b>Question ${i+1}</b> (teacher scored)<div class="qtext" style="font-size:21px">${esc(q.q)}</div><div class="warn">Your answer: ${esc(a.ans[q.id]||"(no answer)")}</div></div>`;
  const ok=a.ok[q.id],pp=qPts(it,q,a);
  return `<div class="rq"><b>Question ${i+1}</b> <span class="${ok?"ok":"no"}">${ok?"Correct":"Not correct"}</span> <span class="tip">${pp} of ${PPQ} points</span><div class="qtext" style="font-size:21px">${esc(q.q)}</div>${q.fig?`<div class="fig">${q.fig}</div>`:""}<div>Your answer: <b>${esc(a.ans[q.id]===undefined||a.ans[q.id]===""?"(no answer)":a.ans[q.id])}</b></div>${ok?"":`<div>Correct answer: <b>${esc(answerText(q))}</b></div><div class="tip">Review: ${esc(MANUAL[q.mod].title)}</div>`}</div>`;
 }).join("");
 app.innerHTML=topbar()+`<div class="card" style="margin-top:12px"><button class="ghost" id="hang">Back to hangar</button><h2 style="font-size:32px;margin-top:12px">${esc(it.title)}: Results</h2><div class="row" style="align-items:flex-end"><div class="big">${r.pct.toFixed(0)}%</div><div><div>${r.earned} of ${r.total} points${it.type==="hw"?` | First try: ${r.firstPct.toFixed(0)}%`:""}</div><div class="tip">Time: about ${Math.max(1,Math.round(a.secs/60))} minutes (suggested ${it.min})</div></div></div>${r.done&&fleetOf(it.id)?`<p class="idea" style="margin:14px 0 0">Unlocked for your museum:</p>${factHTML(it.id)}`:""}${keywordFor(it)?`<div class="warn" style="font-size:22px">Mission keyword: <b>${esc(keywordFor(it))}</b><br><span style="font-size:18px">Type this keyword into the Learning Lab assignment so your teacher can record your score.</span></div>`:""}${it.type==="project"?`<div class="warn">This percent is only the number parts. Your teacher scores the writing parts separately.</div>`:""}<div class="row"><button id="copy">Copy my report</button></div></div><div class="card review" style="margin-top:16px">${items}</div>`;
 bindTop();
 $("#hang").onclick=home;
 $("#copy").onclick=()=>copyReport(id);
}
function reportText(id){
 const it=itemById(id),a=A(id),qs=qOrder(id),r=result(it);
 let t=`${CFG.student}: ${it.title}\nMission keyword: ${keywordFor(it)||"(not finished)"}\nScore: ${r.earned} of ${r.total} points (${r.pct.toFixed(0)}%)\nTime: about ${Math.max(1,Math.round(a.secs/60))} minutes\n\n`;
 qs.forEach((q,i)=>{t+=`${i+1}. ${q.t==="text"?"(written) ":(a.ok[q.id]?"Correct":"Not correct")+" ("+qPts(it,q,a)+" pts) | "}Answer: ${a.ans[q.id]||"(no answer)"}\n`;});
 return t;
}
function copyReport(id){
 const t=reportText(id);
 const done=()=>{const b=$("#copy");if(b){b.textContent="Copied!";setTimeout(()=>b.textContent="Copy my report",1800);}};
 if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(t).then(done,()=>fallbackCopy(t,done));else fallbackCopy(t,done);
}
function fallbackCopy(t,cb){const ta=document.createElement("textarea");ta.value=t;document.body.appendChild(ta);ta.select();try{document.execCommand("copy");}catch(e){}ta.remove();cb();}

/* ===== lessons and guided practice ===== */
const lessonById=id=>LESSONS.find(l=>l.id===id);
const PRIZES=[{t:"Golden Wings",x:"You earned the Golden Wings badge for never giving up on a tough question.",m:5},{t:"Jet Stream Boost",x:"A secret jet stream carried you farther than planned.",m:10},{t:"Pilot Fun Fact",x:"The Wright brothers’ first flight (120 feet) was shorter than the wingspan of a Boeing 747.",m:3},{t:"Secret Hangar Pass",x:"You found a hidden hangar full of bonus fuel.",m:7},{t:"Ace Pilot Joke",x:"Why did the airplane get sent to its room? It was too fly for its own good.",m:3}];
let PR=null;
function lessonBody(l){return `<p class="idea">${esc(l.idea)}</p><h3>Key ideas</h3><ul>${l.points.map(x=>`<li>${esc(x)}</li>`).join("")}</ul><div class="scenario"><b>Try it together:</b> ${esc(l.ex_q)}</div><ol>${l.ex_steps.map(x=>`<li>${esc(x)}</li>`).join("")}</ol>`;}
function learn(lid){
 const l=lessonById(lid);V={view:"learn",id:lid};
 app.innerHTML=topbar()+`<div class="card manual" style="margin-top:12px"><button class="ghost" id="hang">Back to lessons</button><div style="margin-top:12px"><span class="chip">${esc(MANUAL[l.mod].title)}</span></div><h2 style="font-size:32px;margin:8px 0">${esc(l.title)}</h2>${factHTML(l.id)}${lessonBody(l)}<div class="row"><button id="startp">Start guided practice</button><button class="ghost" id="manb">Flight manual</button></div></div>`;
 S.seen=S.seen||{};if(!S.seen[lid]){S.seen[lid]=true;save();}
 $("#hang").onclick=home;$("#startp").onclick=()=>startPractice(lid);$("#manb").onclick=()=>openManual([l.mod]);
}
function openLesson(l){modal(`<h2>${esc(l.title)}</h2>${lessonBody(l)}<div class="row"><button id="mclose">Close</button></div>`);$("#mclose").onclick=closeModal;}
function pChips(){return `<span class="pchip">Miles ${S.miles}</span><span class="pchip">Drag ${S.drag}</span><span class="pchip">Tailwind ${streak}</span>`;}
function startPractice(lid){
 const l=lessonById(lid);
 PR={lid,i:0,tries:0,first:0,res:[],gained:0,mistakes:0,qs:l.qs.map(q=>Object.assign({},q)),n0:l.qs.length,redos:0,locked:false,queued:false};
 practiceAsk();
}
function practiceAsk(){
 const l=lessonById(PR.lid),Q=PR.qs[PR.i];
 PR.tries=0;PR.locked=false;PR.queued=false;
 PR.opts=shuffled(Q.choices,hashStr(Q.id+(Q.redo?"r"+PR.i:"")));
 V={view:"practice",id:PR.lid};
 const dots=PR.qs.map((q,k)=>`<span class="qdot ${PR.res[k]||""} ${q.redo?"redo":""} ${k===PR.i?"now":""}"></span>`).join("");
 app.innerHTML=topbar()+`<div class="rtop"><button class="ghost" id="hang">Back to lessons</button><b>${esc(l.title)}</b><div id="pchips">${pChips()}</div></div><div class="qdots" aria-label="Progress">${dots}</div>
 <div class="runner"><div class="card"><div class="qnum">Question ${PR.i+1} of ${PR.qs.length}${Q.redo?` <span class="redotag">Redo: no miles</span>`:""}</div><div class="qtext">${esc(Q.q)}</div>${Q.fig?`<div class="fig">${Q.fig}</div>`:""}<p class="tip">Press A, B, C, or D, or tap an answer.</p>
 <div class="choices">${PR.opts.map((o,k)=>`<button class="choice" data-k="${k}"><span class="k">${"ABCD"[k]}</span><span>${esc(o)}</span></button>`).join("")}</div>
 <div class="msg" id="fb" role="status" aria-live="polite"></div>
 <details class="ref"><summary>Flight manual: formulas and how-to</summary>${manualHTML(l.mod)}<div class="row"><button class="ghost" id="relearn" style="font-size:17px;padding:6px 14px">Review this lesson</button></div></details></div>${workHTML(Q)}</div>`;
 $("#hang").onclick=home;
 document.querySelectorAll(".choice").forEach(b=>b.onclick=()=>pPick(+b.dataset.k));
 $("#relearn").onclick=()=>openLesson(l);
 mountWork(Q);
}
function pWrong(Q){
 S.drag++;S.miles=Math.max(0,S.miles-1);streak=0;PR.mistakes++;
 if(!PR.queued){PR.queued=true;PR.res[PR.i]="miss";PR.qs.push(Object.assign({},Q,{redo:true}));PR.redos++;}
}
function pPick(k){
 if(!PR||PR.locked)return;
 const Q=PR.qs[PR.i],btns=document.querySelectorAll(".choice"),btn=btns[k];if(!btn||btn.disabled)return;
 PR.tries++;const fbx=$("#fb");
 if(PR.opts[k]===Q.a){
  PR.locked=true;btn.classList.add("good");
  let pts=0;if(!Q.redo){pts=streak>0?2:1;S.miles+=pts;PR.gained+=pts;}
  if(PR.tries===1){streak++;if(!Q.redo)PR.first++;PR.res[PR.i]="ok";}
  save();
  const msg=Q.redo?"No miles on a redo.":(pts===2?"Tailwind! +2 miles.":"+1 mile.");
  fbx.className="msg show good";fbx.innerHTML=`${PR.tries===1?"Correct!":"You got it!"} ${msg}<small>How to get it: ${esc(Q.how)}</small><div class="row"><button id="pnext" style="background:#04210f;color:#fff">${PR.i===PR.qs.length-1?"Finish":"Next"}</button></div>`;
  $("#pnext").onclick=pAdvance;$("#pnext").focus();
 }else{
  btn.classList.add("bad");btn.disabled=true;pWrong(Q);save();
  if(PR.tries<2){fbx.className="msg show bad";fbx.innerHTML=`Not quite. Try again!<small>-1 mile and +1 drag. This question will come back at the end of the lesson. Think it through together, then pick another answer.</small>`;}
  else{
   PR.locked=true;btns.forEach((b,j)=>{b.disabled=true;if(PR.opts[j]===Q.a)b.classList.add("good");});
   fbx.className="msg show bad";fbx.innerHTML=`The answer is ${esc(Q.a)}.<small>How to get it: ${esc(Q.how)}</small><div class="row"><button id="pnext" style="background:#fff;color:#c4001a">${PR.i===PR.qs.length-1?"Finish":"Next"}</button></div>`;
   $("#pnext").onclick=pAdvance;$("#pnext").focus();
  }
 }
 const pc=$("#pchips");if(pc)pc.innerHTML=pChips();
}
function pAdvance(){PR.i++;if(PR.i<PR.qs.length)practiceAsk();else pFinish();}
function pFinish(){
 const l=lessonById(PR.lid),n=PR.n0,r=PR.first/n,st=r>=.9?3:r>=.7?2:1;
 const prev=S.p[l.id]||{stars:0};
 S.p[l.id]={done:true,stars:Math.max(prev.stars||0,st)};save();
 const TL=termLessons(TERM_MODS[1].includes(l.mod)?1:2),idx=TL.findIndex(x=>x.id===l.id),nx=TL[idx+1];
 V={view:"pfinish",id:l.id};
 app.innerHTML=topbar()+`<section class="card" style="margin-top:12px;text-align:center"><h2 style="font-size:34px;color:var(--accent)">Lesson complete!</h2><p>${esc(l.title)}</p><div class="row" style="justify-content:center">${[1,2,3].map(k=>starSVG(k<=st)).join("")}</div><p>${PR.first} of ${n} right on the first try. Miles earned: ${PR.gained}. Mistakes (drag): ${PR.mistakes}.</p>${PR.redos>0?`<div class="scenario" style="max-width:520px;margin:12px auto"><b>Mystery surprise unlocked!</b><br>You finished every missed question. Open the box to see what you won.<div class="row" style="justify-content:center"><button id="mbox">Open mystery box</button></div><div id="mprize" aria-live="polite"></div></div>`:""}<div class="row" style="justify-content:center">${nx?`<button id="pnxt">Next lesson: ${esc(nx.title)}</button>`:""}<button class="ghost" id="pagain">Practice again</button><button class="ghost" id="ptomap">Back to lessons</button></div></section>`;
 if(nx)$("#pnxt").onclick=()=>learn(nx.id);
 $("#pagain").onclick=()=>startPractice(l.id);$("#ptomap").onclick=home;
 const mb=$("#mbox");
 if(mb)mb.onclick=()=>{const p=PRIZES[Math.floor(Math.random()*PRIZES.length)];S.miles+=p.m;save();mb.disabled=true;mb.textContent="Box opened!";$("#mprize").innerHTML=`<div class="prize"><b>${esc(p.t)}</b><br>${esc(p.x)}<br><b>+${p.m} bonus miles</b></div>`;};
}
document.addEventListener("keydown",e=>{
 if(V.view!=="practice"||!PR||e.ctrlKey||e.metaKey||e.altKey||!$("#modal").hidden)return;
 const k="abcd".indexOf(e.key.toLowerCase());
 if(e.key.length===1&&k>-1&&document.activeElement.tagName!=="TEXTAREA")pPick(k);
});

/* ===== timer ===== */
setInterval(()=>{
 if(V.view!=="run"||document.hidden)return;
 const a=S.a[V.id];if(!a)return;a.secs++;
 const el=$("#timer");if(el){el.textContent=fmtTime(a.secs);el.classList.toggle("over",a.secs>itemById(V.id).min*60);}
 if(a.secs%15===0)save();
},1000);
window.addEventListener("beforeunload",()=>{try{localStorage.setItem(localKey(),JSON.stringify(S));}catch(e){}if(CLOUD&&cloudT){clearTimeout(cloudT);pushCloud();}});

/* ===== start ===== */
function newest(list){return list.filter(x=>x&&x.a).sort((a,b)=>(b.updated||0)-(a.updated||0))[0]||null;}
function boot(){
 CLOUD=!!(window.google&&google.script&&google.script.run);
 if(!CLOUD&&window.PILOT_SHELL&&(boot.waits=(boot.waits||0)+1)<30){setTimeout(boot,100);return;}
 if(!CLOUD){const saved=loadLocal();if(saved)S=saved;home();return;}
 app.innerHTML=topbar()+`<div class="card signin"><h2>Loading your progress...</h2></div>`;
 const fail=()=>{app.innerHTML=topbar()+`<div class="card signin"><h2>Could not load your progress</h2><p>Make sure you are signed in with your school Google account and connected to the internet, then try again.</p><div class="row" style="justify-content:center"><button id="retry">Try again</button></div></div>`;$("#retry").onclick=boot;};
 google.script.url.getLocation(loc=>{
  let carried=null;const m=/(?:^|&)import=([^&]+)/.exec(loc.hash||"");
  if(m){try{carried=JSON.parse(decodeURIComponent(escape(atob(decodeURIComponent(m[1])))));}catch(e){}try{google.script.history.replace(null,{},"");}catch(e){}}
  google.script.run.withSuccessHandler(res=>{
   WHO=res.email||"";let cloud=null;try{cloud=res.data?JSON.parse(res.data):null;}catch(e){}
   const best=newest([cloud,loadLocal(),carried]);
   if(best){S=best;S.p=S.p||{};S.miles=S.miles||0;S.drag=S.drag||0;}
   home();
  }).withFailureHandler(fail).getProgress();
 });
}
boot();
